-- Company dimension for the universe.
CREATE SCHEMASTORE VIEW company WITH CONTAINER edgar AS
SELECT
    'TGT' AS ticker,
    cik,
    name AS entity_name,
    sic AS sic_code,
    `sicDescription` AS sic_description,
    `fiscalYearEnd` AS fiscal_year_end_mmdd,
    '' AS comparability_note
FROM sec_data.tgt_submissions_raw
UNION ALL
SELECT
    'WMT' AS ticker,
    cik,
    name AS entity_name,
    sic AS sic_code,
    `sicDescription` AS sic_description,
    `fiscalYearEnd` AS fiscal_year_end_mmdd,
    '' AS comparability_note
FROM sec_data.wmt_submissions_raw
UNION ALL
SELECT
    'COST' AS ticker,
    cik,
    name AS entity_name,
    sic AS sic_code,
    `sicDescription` AS sic_description,
    `fiscalYearEnd` AS fiscal_year_end_mmdd,
    '' AS comparability_note
FROM sec_data.cost_submissions_raw
UNION ALL
SELECT
    'KR' AS ticker,
    cik,
    name AS entity_name,
    sic AS sic_code,
    `sicDescription` AS sic_description,
    `fiscalYearEnd` AS fiscal_year_end_mmdd,
    'cost_of_sales excludes depreciation and amortization, so gross margin is not directly comparable to peers.' AS comparability_note
FROM sec_data.kr_submissions_raw
UNION ALL
SELECT
    'DG' AS ticker,
    cik,
    name AS entity_name,
    sic AS sic_code,
    `sicDescription` AS sic_description,
    `fiscalYearEnd` AS fiscal_year_end_mmdd,
    '' AS comparability_note
FROM sec_data.dg_submissions_raw
UNION ALL
SELECT
    'DLTR' AS ticker,
    cik,
    name AS entity_name,
    sic AS sic_code,
    `sicDescription` AS sic_description,
    `fiscalYearEnd` AS fiscal_year_end_mmdd,
    '' AS comparability_note
FROM sec_data.dltr_submissions_raw
UNION ALL
SELECT
    'BBY' AS ticker,
    cik,
    name AS entity_name,
    sic AS sic_code,
    `sicDescription` AS sic_description,
    `fiscalYearEnd` AS fiscal_year_end_mmdd,
    '' AS comparability_note
FROM sec_data.bby_submissions_raw;
